var vocabulary = ['DNA', 'evolution', 'parsing', 'phonology'];
var eta = ones([vocabulary.length, 1]);

var numTopics = 2;
var alpha = ones([numTopics, 1]);

var corpus = [
  'DNA evolution DNA evolution DNA evolution DNA evolution DNA evolution'.split(' '),
  'DNA evolution DNA evolution DNA evolution DNA evolution DNA evolution'.split(' '),
  'DNA evolution DNA evolution DNA evolution DNA evolution DNA evolution'.split(' '),
  'parsing phonology parsing phonology parsing phonology parsing phonology parsing phonology'.split(' '),
  'parsing phonology parsing phonology parsing phonology parsing phonology parsing phonology'.split(' '),
  'parsing phonology parsing phonology parsing phonology parsing phonology parsing phonology'.split(' ')
];
var ANSWER = (Infer({method: 'MCMC', samples: 200, lag: 50}, function() {
  var topics = repeat(numTopics, function() {
    return T.toScalars(dirichlet({alpha: eta}));
  });

  mapData({data: corpus}, function(doc) {
    var docTopicDist = dirichlet({alpha: alpha});
    mapData({data: doc}, function(word) {
      var z = discrete(docTopicDist);
      var topic = topics[z];
      observe(Categorical({vs: vocabulary, ps: topic}), word);
    });
  });
  return topics;
}));

var observedData = [{C:true, E:false}];
var ANSWER = (Infer({method: 'MCMC', samples: 10000, lag:2}, function() {
  var relation = flip();
  var cp = uniform(0, 1);
  var b = uniform(0, 1);

  var noisyOrMarginal = function(C) {
    return Infer({method: 'enumerate'}, function() {
      return (relation && C && flip(cp)) || flip(b);
    });
  };

  mapData({data: observedData}, function(datum) {
    observe(noisyOrMarginal(datum.C), datum.E);
  });

  return {relation, cp, b};
}));
